arguments.command:
python3 -c '
import json, re

def check_boxed(output, gt):
    # Find last \boxed{...}
    matches = re.findall(r"\\boxed\{([^}]*)\}", output)
    if not matches:
        return False, None
    last = matches[-1].replace(",", "").strip()
    try:
        return float(last) == float(gt), last
    except:
        return last == str(gt), last

for step in [0, 50, 100]:
    path = f"/workspace/results/run100/val_generations/{step}.jsonl"
    with open(path) as f:
        lines = [json.loads(l) for l in f]
    mv_scores = [l["score"] for l in lines]
    boxed_scores = []
    has_boxed = 0
    mv_true_no_boxed = 0
    for l in lines:
        ok, extr = check_boxed(l["output"], l["gts"])
        boxed_scores.append(1.0 if ok else 0.0)
        if extr is not None:
            has_boxed += 1
        elif l["score"] > 0.5:
            mv_true_no_boxed += 1
    print(f"VAL step {step:3d}: math_verify_acc={sum(mv_scores)/len(mv_scores):.4f}, boxed_acc={sum(boxed_scores)/len(boxed_scores):.4f}, has_boxed={has_boxed}/{len(lines)} ({has_boxed/len(lines):.3f}), mv_true_but_no_boxed={mv_true_no_boxed}")
'

