"""Reward: Exact numerical match between the response's last \\boxed{...} answer and the gold answer.

Replaces the subprocess-based ``math_verify.compute_score`` wrapper, which suffered from:
1. Subprocess pool crashes/timeouts during concurrent validation scoring (silently zeroing out valid
   boxed answers).
2. Unboxed fallback extraction (``ExprExtractionConfig``), which rewarded truncated or repetitive
   responses that never produced a final ``\\boxed{...}`` answer.
"""

from verl.utils.reward_score.math_reward import last_boxed_only_string, remove_boxed, strip_string


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    if not solution_str:
        return 0.0
    try:
        boxed = last_boxed_only_string(solution_str)
        if boxed is None:
            return 0.0
        ans = remove_boxed(boxed).strip()
        # Clean standard numeric formatting (commas, dollar signs, spaces, units via strip_string)
        cleaned = strip_string(ans).replace(",", "").replace("$", "").strip()
        gt_clean = str(ground_truth).replace(",", "").replace("$", "").strip()
        try:
            if abs(float(cleaned) - float(gt_clean)) < 1e-6:
                return 1.0
        except ValueError:
            pass
        if cleaned == strip_string(gt_clean):
            return 1.0
    except Exception:
        pass
    return 0.0

